#include <iostream>
#include <vector>
#include <queue>
using namespace std;int main(){int n;cin>>n;if(!n){cout<<0;return 0;}vector<vector<int>>a(n+1);int root=0;for(int i=1,p;i<=n;i++){cin>>p;if(!p)root=i;else a[p].push_back(i);}queue<pair<int,int>>q;q.push({root,1});int answer=0;while(!q.empty()){auto t=q.front();q.pop();answer=max(answer,t.second);for(int v:a[t.first])q.push({v,t.second+1});}cout<<answer;}

