#include <iostream>
#include <vector>
#include <queue>
#include <functional>
using namespace std;int main(){int n,m,s,t;cin>>n>>m>>s>>t;using P=pair<long long,int>;vector<vector<pair<int,long long>>>a(n+1);for(int i=0,u,v;i<m;i++){long long w;cin>>u>>v>>w;a[u].push_back({v,w});}const long long INF=4000000000000000000LL;vector<long long>d(n+1,INF);priority_queue<P,vector<P>,greater<P>>q;d[s]=0;q.push({0,s});while(!q.empty()){auto cur=q.top();q.pop();if(cur.first!=d[cur.second])continue;for(auto e:a[cur.second])if(cur.first+e.second<d[e.first]){d[e.first]=cur.first+e.second;q.push({d[e.first],e.first});}}cout<<(d[t]==INF?-1:d[t]);}

